// SCL — Stage 2 inter-outlet transfer (multi-drop aware).
// On the receiving leg of a Material Transfer, compute qty variance %
// vs the outgoing SE. For multi-drop dispatches, use only the drops
// allocated to THIS receipt SE (destination_allocations rows where
// receipt_stock_entry == this doc's name) as the baseline.
frappe.ui.form.on('Stock Entry', {
    refresh:  function(frm) { recompute_inter_outlet_variance(frm); },
    validate: function(frm) { recompute_inter_outlet_variance(frm); }
});
frappe.ui.form.on('Stock Entry Detail', {
    qty:          function(frm) { recompute_inter_outlet_variance(frm); },
    items_remove: function(frm) { recompute_inter_outlet_variance(frm); }
});

async function recompute_inter_outlet_variance(frm) {
    if (frm.doc.purpose !== 'Material Transfer') return;
    if (!frm.doc.outgoing_stock_entry) return;

    let outgoing;
    try {
        outgoing = await frappe.db.get_doc('Stock Entry', frm.doc.outgoing_stock_entry);
    } catch (e) { return; }

    // Build per-item dispatched baseline.
    const dispatched_by_item = {};
    if (outgoing.is_multi_drop) {
        // Multi-drop: only sum allocations mapped to THIS receipt.
        const my_name = frm.doc.name;
        for (const a of (outgoing.destination_allocations || [])) {
            if (a.receipt_stock_entry !== my_name) continue;
            const qty = (a.weighbridge_qty || a.allocated_qty || 0);
            dispatched_by_item[a.item_code] =
                (dispatched_by_item[a.item_code] || 0) + qty;
        }
    } else {
        // Single-drop legacy: sum all outgoing items.
        for (const r of (outgoing.items || [])) {
            dispatched_by_item[r.item_code] =
                (dispatched_by_item[r.item_code] || 0) + (r.qty || 0);
        }
    }

    // Sum received per item.
    const received_by_item = {};
    for (const r of (frm.doc.items || [])) {
        received_by_item[r.item_code] =
            (received_by_item[r.item_code] || 0) + (r.qty || 0);
    }

    let total_dispatched = 0, total_diff_abs = 0;
    for (const code of Object.keys(dispatched_by_item)) {
        const d = dispatched_by_item[code] || 0;
        const r = received_by_item[code] || 0;
        total_dispatched += d;
        total_diff_abs   += Math.abs(d - r);
    }
    const pct = total_dispatched
        ? Math.round((total_diff_abs / total_dispatched) * 10000) / 100
        : 0;
    if ((frm.doc.variance_pct || 0) !== pct) frm.set_value('variance_pct', pct);
}

// Sungas · Material Request client-side enhancements
// Managed by /app/scripts/install_stage4_mr_ux_fixes.py — do not hand-edit.

frappe.ui.form.on("Material Request", {
    onload(frm) {
        _sungas_set_indicator(frm);
        _sungas_apply_from_warehouse_filter(frm);
        if (frm.is_new() && !frm.doc.set_warehouse) {
            _sungas_prefill_destination(frm);
        }
        _sungas_prefill_transit_source(frm);
    },
    refresh(frm) {
        _sungas_set_indicator(frm);
        _sungas_apply_from_warehouse_filter(frm);
    },
    material_request_type(frm) {
        _sungas_apply_from_warehouse_filter(frm);
        _sungas_prefill_transit_source(frm);
    },
    hoo_approved(frm) {
        _sungas_set_indicator(frm);
    },
});

frappe.ui.form.on("Material Request Item", {
    items_add(frm, cdt, cdn) {
        // New row appended — if the parent MR is a Material Transfer and
        // the row's from_warehouse is empty, default it to GIT so
        // downstream SE builder picks up the correct 3-leg pattern.
        if (frm.doc.material_request_type === "Material Transfer") {
            const row = locals[cdt][cdn];
            if (row && !row.from_warehouse) {
                frappe.model.set_value(cdt, cdn, "from_warehouse", "Goods In Transit - SCL");
            }
        }
    },
    warehouse(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.warehouse) return;
        // Small delay so Frappe's own item-default fetch finishes first,
        // then we overwrite with the warehouse-scoped values.
        setTimeout(() => {
            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Warehouse", name: row.warehouse },
                callback: (r) => {
                    const v = r.message || {};
                    if (v.custom_default_cost_center) {
                        frappe.model.set_value(cdt, cdn, "cost_center", v.custom_default_cost_center);
                    }
                    if (v.custom_sungas_region) {
                        frappe.model.set_value(cdt, cdn, "sungas_region", v.custom_sungas_region);
                    }
                    if (v.custom_sungas_branch) {
                        frappe.model.set_value(cdt, cdn, "branch", v.custom_sungas_branch);
                    }
                }
            });
        }, 400);
    }
});

// ── helpers ──────────────────────────────────────────────────────────
function _sungas_set_indicator(frm) {
    if (!frm.doc || frm.is_new()) return;
    if (frm.doc.material_request_type !== "Material Transfer") return;
    let label = null, colour = null;
    if (frm.doc.docstatus === 0) {
        label = "Draft"; colour = "gray";
    } else if (!frm.doc.hoo_approved) {
        label = "Awaiting HoO Approval"; colour = "yellow";
    } else if (!frm.doc.per_ordered) {
        label = "HoO Approved · Awaiting Dispatch"; colour = "green";
    } else if (frm.doc.per_received < 100) {
        label = "Dispatched · Awaiting Receipt"; colour = "blue";
    } else {
        label = "Received"; colour = "green";
    }
    if (label) frm.page.set_indicator(label, colour);
}

function _sungas_apply_from_warehouse_filter(frm) {
    const is_transfer = frm.doc.material_request_type === "Material Transfer";
    const filt = is_transfer
        ? {"warehouse_name": ["like", "Goods In Transit%"], "disabled": 0, "is_group": 0}
        : {"warehouse_name": ["not like", "Goods In Transit%"], "disabled": 0, "is_group": 0};
    frm.set_query("from_warehouse", "items", () => ({ filters: filt }));
    frm.set_query("set_from_warehouse", () => ({ filters: filt }));
}

async function _sungas_prefill_destination(frm) {
    // Look up Warehouse where outlet_plant_manager = current user, then set as destination.
    const r = await new Promise((resolve) => {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Warehouse",
                filters: {"outlet_plant_manager": frappe.session.user, "disabled": 0, "is_group": 0},
                fields: ["name"],
                limit_page_length: 1
            },
            callback: (res) => resolve(res.message || [])
        });
    });
    if (r && r.length) {
        frm.set_value("set_warehouse", r[0].name);
    }
}

function _sungas_prefill_transit_source(frm) {
    // For Material Transfer MRs, default the source-warehouse pointer to
    // GIT so downstream SE builders (destination PM's "Get Items From MR")
    // start with GIT → destination. Source PM's Client Script remap flips
    // it to source_outlet → GIT on their side when needed. The Sungas
    // `source_outlet` field carries the true origin as a semantic layer.
    if (frm.doc.material_request_type !== "Material Transfer") return;
    if (frm.doc.set_from_warehouse) return;
    frm.set_value("set_from_warehouse", "Goods In Transit - SCL");
    // Cascade to any existing rows without from_warehouse.
    (frm.doc.items || []).forEach((row) => {
        if (!row.from_warehouse) {
            frappe.model.set_value(row.doctype, row.name, "from_warehouse", "Goods In Transit - SCL");
        }
    });
}

// Sungas · Stock Entry auto-populate for Material Transfers
// Managed by installer — do not hand-edit.

frappe.ui.form.on("Stock Entry", {
    onload(frm) {
        sungas_apply_se_defaults(frm);
        sungas_apply_item_defaults(frm);
        sungas_maybe_remap(frm);
    },
    refresh(frm) {
        sungas_apply_se_defaults(frm);
        sungas_apply_item_defaults(frm);
        sungas_maybe_remap(frm);
    },
    stock_entry_type(frm) {
        sungas_apply_se_defaults(frm);
        sungas_apply_item_defaults(frm);
    },
    company(frm) {
        sungas_apply_item_defaults(frm);
    },
    material_request_new(frm) {
        sungas_maybe_remap(frm, /* force */ true);
    }
});

async function sungas_apply_se_defaults(frm) {
    if (!frm.is_new()) return;
    if (frm.doc.stock_entry_type !== "Material Transfer") return;
    if (!frm.doc.from_warehouse) {
        const w = await sungas_user_outlet();
        if (w) frm.set_value("from_warehouse", w);
    }
    if (!frm.doc.to_warehouse) {
        frm.set_value("to_warehouse", "Goods In Transit - SCL");
    }
}

function sungas_user_outlet() {
    return new Promise((resolve) => {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Warehouse",
                filters: {"outlet_plant_manager": frappe.session.user, "disabled": 0, "is_group": 0},
                fields: ["name"],
                limit_page_length: 1
            },
            callback: (res) => resolve(((res && res.message) || [])[0]?.name || null)
        });
    });
}

function sungas_get_warehouse_defaults(warehouse) {
    return new Promise((resolve) => {
        if (!warehouse) return resolve({});
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Warehouse",
                filters: { name: warehouse },
                fieldname: ["custom_default_cost_center", "custom_sungas_region", "custom_sungas_branch"]
            },
            callback: (res) => resolve((res && res.message) || {})
        });
    });
}

function sungas_get_company_defaults(company) {
    return new Promise((resolve) => {
        if (!company) return resolve({});
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Company",
                filters: { name: company },
                fieldname: ["stock_adjustment_account", "default_expense_account"]
            },
            callback: (res) => resolve((res && res.message) || {})
        });
    });
}

async function sungas_maybe_remap(frm, force) {
    // Runs on refresh / onload / material_request_new / items_add and
    // re-runs the source-vs-destination remap when needed. Idempotent —
    // guarded by a stamp so we don't loop.
    if (!frm.is_new()) return;
    if (frm.doc.stock_entry_type !== "Material Transfer") return;
    if (!frm.doc.material_request_new) return;
    if (!(frm.doc.items || []).length) return;

    const stamp = frm.doc.material_request_new + "|" + (frm.doc.items || []).length;
    if (!force && frm.__sungas_remap_stamp === stamp) return;
    frm.__sungas_remap_stamp = stamp;

    await sungas_remap_from_mr(frm);
}

async function sungas_remap_from_mr(frm) {
    const mr = await new Promise((resolve) => {
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Material Request",
                filters: { name: frm.doc.material_request_new },
                fieldname: ["source_outlet", "set_warehouse"]
            },
            callback: (res) => resolve((res && res.message) || {})
        });
    });
    if (!mr.source_outlet || !mr.set_warehouse) return;

    const user_outlet = await sungas_user_outlet();
    const GIT = "Goods In Transit - SCL";
    let src, dst;
    if (user_outlet && user_outlet === mr.source_outlet) {
        src = mr.source_outlet; dst = GIT;
    } else if (user_outlet && user_outlet === mr.set_warehouse) {
        src = GIT; dst = mr.set_warehouse;
    } else {
        return;
    }

    // Only remap if the current warehouses don't already match.
    if (frm.doc.from_warehouse === src && frm.doc.to_warehouse === dst) {
        // Still make sure item defaults are stamped.
    } else {
        frm.set_value("from_warehouse", src);
        frm.set_value("to_warehouse", dst);
    }

    const outlet_wh = (src === GIT) ? dst : src;
    const defs = await sungas_get_warehouse_defaults(outlet_wh);
    const company = await sungas_get_company_defaults(frm.doc.company);

    (frm.doc.items || []).forEach((row) => {
        frappe.model.set_value(row.doctype, row.name, "s_warehouse", src);
        frappe.model.set_value(row.doctype, row.name, "t_warehouse", dst);
        if (defs.custom_default_cost_center) {
            frappe.model.set_value(row.doctype, row.name, "cost_center", defs.custom_default_cost_center);
        }
        if (defs.custom_sungas_region) {
            frappe.model.set_value(row.doctype, row.name, "sungas_region", defs.custom_sungas_region);
        }
        if (defs.custom_sungas_branch) {
            frappe.model.set_value(row.doctype, row.name, "branch", defs.custom_sungas_branch);
        }
        if (company.stock_adjustment_account) {
            const current = row.expense_account;
            if (!current || current === company.default_expense_account) {
                frappe.model.set_value(row.doctype, row.name, "expense_account", company.stock_adjustment_account);
            }
        }
    });
}

async function sungas_apply_item_defaults(frm) {
    if (!frm.doc.company) return;
    if (!frm.doc.items || !frm.doc.items.length) return;
    const company = await sungas_get_company_defaults(frm.doc.company);
    if (!company.stock_adjustment_account) return;
    const is_transfer = frm.doc.stock_entry_type === "Material Transfer";
    (frm.doc.items || []).forEach((row) => {
        const current = row.expense_account;
        if (is_transfer && (!current || current === company.default_expense_account)) {
            frappe.model.set_value(row.doctype, row.name, "expense_account", company.stock_adjustment_account);
        } else if (!current) {
            frappe.model.set_value(row.doctype, row.name, "expense_account", company.stock_adjustment_account);
        }
    });
}

frappe.ui.form.on("Stock Entry Detail", {
    items_add(frm, cdt, cdn) {
        setTimeout(() => {
            sungas_apply_item_defaults(frm);
            sungas_maybe_remap(frm);
        }, 200);
    },
    s_warehouse(frm, cdt, cdn) {
        sungas_fill_cc(frm, cdt, cdn, locals[cdt][cdn].s_warehouse);
    },
    t_warehouse(frm, cdt, cdn) {
        sungas_fill_cc(frm, cdt, cdn, locals[cdt][cdn].t_warehouse);
    }
});

function sungas_fill_cc(frm, cdt, cdn, warehouse) {
    if (!warehouse) return;
    if (warehouse === "Goods In Transit - SCL") return;
    setTimeout(() => {
        frappe.call({
            method: "frappe.client.get",
            args: { doctype: "Warehouse", name: warehouse },
            callback: (r) => {
                const v = r.message || {};
                if (v.custom_default_cost_center) {
                    frappe.model.set_value(cdt, cdn, "cost_center", v.custom_default_cost_center);
                }
                if (v.custom_sungas_region) {
                    frappe.model.set_value(cdt, cdn, "sungas_region", v.custom_sungas_region);
                }
                if (v.custom_sungas_branch) {
                    frappe.model.set_value(cdt, cdn, "branch", v.custom_sungas_branch);
                }
            }
        });
    }, 300);
}

// Sungas · DLS drop-table enhancements v2
// - Dropdown filter: only approved Material Transfer MRs whose source matches this DLS
// - Excludes MRs already added to the current DLS
// - On selection: auto-fill destination/item/qty (fields become read-only)
// - Reject wrong source outlet or duplicate on selection

frappe.ui.form.on("Daily Loading Schedule", {
    onload(frm) {
        sungas_dls_apply_mr_filter(frm);
    },
    refresh(frm) {
        sungas_dls_apply_mr_filter(frm);
    },
    source_outlet(frm) {
        sungas_dls_apply_mr_filter(frm);
    }
});

frappe.ui.form.on("Schedule Drop", {
    material_request(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.material_request) return;

        // Reject duplicates
        const dupes = (frm.doc.drops || []).filter(
            d => d.name !== row.name && d.material_request === row.material_request
        );
        if (dupes.length) {
            frappe.msgprint({
                title: __("Duplicate MR"),
                indicator: "red",
                message: __("MR <b>{0}</b> is already on this Loading Schedule.", [row.material_request])
            });
            frappe.model.set_value(cdt, cdn, "material_request", "");
            return;
        }

        // Fetch MR and validate
        frappe.call({
            method: "frappe.client.get",
            args: { doctype: "Material Request", name: row.material_request },
            callback: (r) => {
                const mr = r.message || {};
                if (mr.material_request_type !== "Material Transfer") {
                    frappe.msgprint({
                        title: __("Wrong MR type"),
                        indicator: "red",
                        message: __("Only <b>Material Transfer</b> MRs can be scheduled.")
                    });
                    frappe.model.set_value(cdt, cdn, "material_request", "");
                    return;
                }
                if (!mr.hoo_approved || mr.docstatus !== 1) {
                    frappe.msgprint({
                        title: __("Not approved"),
                        indicator: "red",
                        message: __("MR <b>{0}</b> is not yet HoO-approved.", [mr.name])
                    });
                    frappe.model.set_value(cdt, cdn, "material_request", "");
                    return;
                }
                // Source-outlet gate — a DLS is scoped to ONE loading outlet (its source)
                if (frm.doc.source_outlet && mr.source_outlet && mr.source_outlet !== frm.doc.source_outlet) {
                    frappe.msgprint({
                        title: __("Wrong source outlet"),
                        indicator: "red",
                        message: __("MR <b>{0}</b> is being loaded from <b>{1}</b>, but this Loading Schedule is for <b>{2}</b>. Create a separate DLS for {1} or fix the MR's source outlet.",
                            [mr.name, mr.source_outlet, frm.doc.source_outlet])
                    });
                    frappe.model.set_value(cdt, cdn, "material_request", "");
                    return;
                }
                frappe.model.set_value(cdt, cdn, "destination_outlet", mr.set_warehouse);
                if (mr.items && mr.items.length) {
                    const it = mr.items[0];
                    frappe.model.set_value(cdt, cdn, "item_code", it.item_code);
                    frappe.model.set_value(cdt, cdn, "qty", it.qty);
                    frappe.model.set_value(cdt, cdn, "uom", it.uom || "Kg");
                }
                frm.refresh_field("drops");
            }
        });
    }
});

function sungas_dls_apply_mr_filter(frm) {
    frm.set_query("material_request", "drops", () => {
        // Exclude MRs already picked on this DLS
        const already = (frm.doc.drops || [])
            .map(d => d.material_request)
            .filter(Boolean);
        const filters = {
            "material_request_type": "Material Transfer",
            "hoo_approved": 1,
            "docstatus": 1,
            "per_ordered": ["<", 100]
        };
        if (frm.doc.source_outlet) {
            filters["source_outlet"] = frm.doc.source_outlet;
        }
        if (already.length) {
            filters["name"] = ["not in", already];
        }
        return { filters };
    });
}

frappe.ui.form.on('Purchase Receipt', {
    refresh(frm) {
        // Remove the standard Close / Re-open status menu items to avoid confusion
        setTimeout(() => {
            frm.page.wrapper.find('.menu-item-label:contains("Close")').closest('.menu-item').remove();
            frm.page.wrapper.find('.menu-item-label:contains("Re-open")').closest('.menu-item').remove();
        }, 500);
    },
});

frappe.ui.form.on('Purchase Receipt', {
    refresh(frm) {
        if (frm.doc.docstatus === 1 && frm.doc.discharge_status !== 'Closed') {
            const has_role = frappe.user.has_role('LPG Head of Operations') ||
                             frappe.user.has_role('System Manager');
            if (has_role) {
                frm.add_custom_button(__('Close Discharge & Reconcile'), () => {
                    frappe.confirm(__('Close discharge? Residual opens a Transit Loss Variance Case.'),
                    () => {
                        frappe.db.get_list('Stock Entry', {
                            filters: [['pr_reference_new','=',frm.doc.name],['docstatus','=',1]],
                            fields:['name'], limit:1, order_by:'creation desc',
                        }).then(ses => {
                            const se_name = (ses && ses.length) ? ses[0].name : null;
                            if (!se_name) {
                                frappe.msgprint({title:__('Cannot close'),
                                    message:__('Requires at least one submitted Stock Entry.'), indicator:'red'}); return;
                            }
                            const residual = flt(frm.doc.remaining_in_git_qty);
                            const rate = flt(frm.doc.items[0] ? frm.doc.items[0].rate : 0);
                            const total_qty = flt(frm.doc.total_qty);
                            const shortfall_ngn = residual * rate;
                            const shortfall_pct = total_qty ? (residual / total_qty * 100) : 0;
                            frappe.call({method:'frappe.client.set_value',
                                args:{doctype:'Purchase Receipt', name:frm.doc.name,
                                      fieldname:{'discharge_status':'Closed',
                                                 'discharge_closed_by':frappe.session.user,
                                                 'discharge_closed_at':frappe.datetime.now_datetime()}},
                                callback: () => {
                                    if (residual < 0.01) {
                                        frappe.msgprint({title:__('Discharge Closed'),
                                            message:__('No residual — case not required.'), indicator:'green'});
                                        frm.reload_doc(); return;
                                    }
                                    frappe.call({method:'frappe.client.insert',
                                        args:{doc:{
                                            doctype:'Transit Loss Variance Case',
                                            purchase_receipt: frm.doc.name,
                                            outlet_receipt_se: se_name,
                                            company: frm.doc.company,
                                            resolution:'Pending',
                                            hauler_type: frm.doc.hauler_type,
                                            hauler: frm.doc.hauler,
                                            in_house_driver: frm.doc.in_house_driver,
                                            qty_waybilled: total_qty,
                                            qty_received: flt(frm.doc.total_discharged_qty),
                                            qty_shortfall: residual,
                                            shortfall_pct: shortfall_pct,
                                            shortfall_value: shortfall_ngn,
                                            opening_date: frappe.datetime.get_today(),
                                            workflow_state:'Draft',
                                        }},
                                        callback:(r2) => {
                                            if (r2 && r2.message && r2.message.name) {
                                                frappe.msgprint({title:__('Discharge Closed'),
                                                    message:__('Residual: ' + residual + ' kg (₦' +
                                                               shortfall_ngn.toLocaleString() + '). Case ' +
                                                               r2.message.name + ' opened.'),
                                                    indicator:'orange'});
                                            }
                                            frm.reload_doc();
                                        }});
                                }});
                        });
                    });
                }, __('Actions'));
            }
        }
    },
});

// Stage 3.3 — Show remaining qty next to each PO in the "Get Items From > Purchase Order" dialog
frappe.ui.form.on('Purchase Receipt', {
    refresh(frm) {
        // Add a helpful info banner
        if (frm.is_new()) {
            frm.dashboard.add_comment(
                __("Tip: Click <b>Get Items From > Purchase Order</b> — the dialog will auto-fill each line with the REMAINING qty on that PO."),
                "blue", true
            );
        }

        // Also print a quick outstanding-PO summary if supplier is set
        if (frm.doc.supplier && frm.is_new()) {
            frappe.db.get_list('Purchase Order', {
                filters: [
                    ['supplier', '=', frm.doc.supplier],
                    ['docstatus', '=', 1],
                    ['per_received', '<', 100],
                    ['status', '!=', 'Closed'],
                ],
                fields: ['name', 'per_received', 'grand_total', 'transaction_date'],
                limit: 5,
                order_by: 'transaction_date desc',
            }).then(pos => {
                if (!pos || !pos.length) return;
                let rows = pos.map(po =>
                    `<tr><td>${po.name}</td><td class="text-right">${po.per_received}%</td>` +
                    `<td class="text-right">${format_currency(po.grand_total, 'NGN')}</td>` +
                    `<td>${po.transaction_date}</td></tr>`
                ).join('');
                frm.dashboard.add_section(
                    `<div class="text-muted"><b>${__("Open POs for this supplier")}</b></div>` +
                    `<table class="table table-condensed"><thead><tr>` +
                    `<th>PO</th><th class="text-right">%Rec'd</th>` +
                    `<th class="text-right">Value</th><th>Date</th></tr></thead>` +
                    `<tbody>${rows}</tbody></table>`,
                    __("Open POs")
                );
            });
        }
    },
});

// Stage 3.2 — Client-side live preview of shortload / auto-fill of qty.
// Runs on the Purchase Receipt Item child table.
frappe.ui.form.on('Purchase Receipt Item', {
    source_weighbridge_qty(frm, cdt, cdn) {
        _sungas_recalc_shortload(frm, cdt, cdn);
    },
    waybill_line_qty(frm, cdt, cdn) {
        _sungas_recalc_shortload(frm, cdt, cdn);
    },
});

function _sungas_recalc_shortload(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const waybill = flt(row.waybill_line_qty);
    const wb      = flt(row.source_weighbridge_qty);

    if (wb > 0) {
        // Weighbridge is authoritative — force qty to match
        frappe.model.set_value(cdt, cdn, 'qty', wb);
        const shortload = (waybill > 0 && waybill > wb) ? (waybill - wb) : 0;
        frappe.model.set_value(cdt, cdn, 'supplier_shortload_qty', shortload);
    } else if (waybill > 0) {
        frappe.model.set_value(cdt, cdn, 'qty', waybill);
        frappe.model.set_value(cdt, cdn, 'supplier_shortload_qty', 0);
    }

    // Roll up on header for immediate visibility
    let total = 0;
    let has_any = 0;
    (frm.doc.items || []).forEach(r => {
        const s = flt(r.supplier_shortload_qty);
        total += s;
        if (s > 0) has_any = 1;
    });
    frm.set_value('has_supplier_shortload', has_any);
    frm.set_value('total_supplier_shortload_qty', total);

    if (has_any) {
        frm.dashboard.clear_headline();
        frm.dashboard.set_headline(
            `<span class="indicator-pill red">Supplier short-load detected: ` +
            `${total.toFixed(3)} kg unaccounted between waybill and weighbridge</span>`
        );
    }
}

// SCL — Stage 1 user-stamping on workflow transitions.
// Frappe Workflow Document State's `update_value` is a literal,
// so we can't put `frappe.session.user` there. Instead, listen for
// the workflow_state change client-side and write the user into
// the right Link field, then save.
frappe.ui.form.on('Purchase Receipt', {
    before_workflow_action: async function(frm) {
        const next = frm.selected_workflow_action;
        if (next === 'Plant Manager Sign' && !frm.doc.plant_manager_signed_by) {
            frm.set_value('plant_manager_signed_by', frappe.session.user);
        }
        if (next === 'Escalate to HOD Ops' && !frm.doc.hod_ops_signed_by) {
            frm.set_value('hod_ops_signed_by', frappe.session.user);
        }
    }
});

// SCL — Stage 1 procurement intake.
// Auto-computes Qty variance vs PO every time a row changes,
// expressed as a percentage of total ordered qty. Used by the
// Sungas Purchase Receipt Approval workflow to route receipts
// with >= 5% variance to HOD Ops.
frappe.ui.form.on('Purchase Receipt', {
    validate: function(frm) {
        recompute_variance(frm);
    },
    refresh: function(frm) {
        recompute_variance(frm);
    }
});
frappe.ui.form.on('Purchase Receipt Item', {
    qty: function(frm) { recompute_variance(frm); },
    purchase_order_item: function(frm) { recompute_variance(frm); },
    items_remove: function(frm) { recompute_variance(frm); }
});

async function recompute_variance(frm) {
    let total_ordered = 0;
    let total_diff_abs = 0;
    for (const row of (frm.doc.items || [])) {
        let po_qty = 0;
        if (row.purchase_order_item) {
            try {
                const res = await frappe.db.get_value(
                    'Purchase Order Item',
                    row.purchase_order_item,
                    'qty'
                );
                po_qty = (res && res.message && res.message.qty) || 0;
            } catch (e) { po_qty = 0; }
        }
        if (po_qty) {
            total_ordered += po_qty;
            total_diff_abs += Math.abs((row.qty || 0) - po_qty);
        }
    }
    const pct = total_ordered ? Math.round((total_diff_abs / total_ordered) * 10000) / 100 : 0;
    if ((frm.doc.qty_variance_pct || 0) !== pct) {
        frm.set_value('qty_variance_pct', pct);
    }
}

// Cashier-side restrictions on Customer form.
// Goal: cashiers (LPG POS User) can CREATE customers only in
// "Retail" group, and CANNOT edit existing customers at all.
frappe.ui.form.on("Customer", {
    refresh(frm) {
        const roles = frappe.user_roles || [];
        const is_cashier = roles.includes("LPG POS User");
        const is_senior = roles.some(r =>
            ["System Manager", "Sales Manager", "Accounts Manager",
             "LPG Plant Manager", "LPG Head of Sales", "LPG Head of Finance"].includes(r)
        );
        if (!is_cashier || is_senior) {
            return;
        }

        if (frm.is_new()) {
            // Cashier is creating a new customer -- lock group to Retail.
            frm.set_value("customer_group", "Retail");
            frm.set_df_property("customer_group", "read_only", 1);
            frm.set_df_property("customer_group", "description",
                "Cashiers may only create customers in the Retail group.");
        } else {
            // Cashier opened an existing customer -- view only.
            frm.disable_save();
            frm.fields.forEach(f => {
                if (f.df && !["customer_name", "customer_group", "territory",
                              "mobile_no", "email_id"].includes(f.df.fieldname)) {
                    return;
                }
            });
            // Make every field read-only.
            for (const fn of Object.keys(frm.fields_dict || {})) {
                try { frm.set_df_property(fn, "read_only", 1); }
                catch (e) { /* ignore */ }
            }
            frm.dashboard.add_indicator(
                __("View only -- cashiers cannot edit customer profiles"), "orange");
        }
    },
});

// Patch 0011 -- when PR is routed through 'Goods in Transit from Suppliers - SCL',
// auto-populate cost center on every line to the HO Procurement CC configured
// on Sungas Procurement Policy (default: '70003 - Procurement - SCL').
// This mirrors the business rule: central purchases are booked to HO Procurement.
//
// Patch 0011d: swallow 403s silently so users without 'Sungas Procurement Policy'
// read-perm don't see a 'Not permitted' popup on every PR form load.
frappe.ui.form.on('Purchase Receipt', {
    onload(frm) { _sungas_pr_prefill_cc(frm); },
    refresh(frm) { _sungas_pr_prefill_cc(frm); },
    set_warehouse(frm) { _sungas_pr_prefill_cc(frm); },
    final_destination_warehouse(frm) { _sungas_pr_prefill_cc(frm); }
});
frappe.ui.form.on('Purchase Receipt Item', {
    items_add(frm) { setTimeout(() => _sungas_pr_prefill_cc(frm), 200); }
});

async function _sungas_pr_prefill_cc(frm) {
    if (!frm.doc || frm.doc.docstatus !== 0) return;
    const GIT = 'Goods in Transit from Suppliers - SCL';
    if (frm.doc.set_warehouse !== GIT) return;
    // Pull HO procurement CC from a public whitelisted method so we don't
    // require per-user read-perm on Sungas Procurement Policy.
    let cc = '70003 - Procurement - SCL';
    try {
        const r = await frappe.call({
            method: 'sungas.api.get_hoi_cost_center',
            type: 'GET',
            no_spinner: true,
            freeze: false
        });
        if (r && r.message) cc = r.message;
    } catch (e) {
        // Non-fatal -- fall back to default. NEVER throw a 'Not permitted' popup.
    }
    (frm.doc.items || []).forEach((row) => {
        if (!row.cost_center || row.cost_center !== cc) {
            frappe.model.set_value(row.doctype, row.name, 'cost_center', cc);
        }
    });
}
